server {
    listen 80 default_server;
    server_name _;
    root /var/www/site;
    index index.html;
}

options {
    directory "/var/cache/bind";
    recursion no;
    allow-query { any; };
};
zone "lumiere-boutique.com" { type primary; file "/etc/bind/db.lumiere-boutique.com"; };

options {
	directory "/var/cache/bind";

	dnssec-validation auto;

	listen-on-v6 { any; };
};

client localhost {
  ipaddr = 127.0.0.1
  secret = testing123
  shortname = localhost
}
client reseau-siege {
  ipaddr = 10.10.0.0/16
  secret = Lum1ere-AAA
  shortname = siege
}
client reseau-reprise {
  ipaddr = 10.20.0.0/16
  secret = Lum1ere-AAA
  shortname = reprise
}

SET ECHO OFF
CREATE TABLESPACE shop_data DATAFILE '/u01/app/oracle/oradata/ORCL/shop_data01.dbf' SIZE 200M;
CREATE TABLESPACE shop_idx DATAFILE '/u01/app/oracle/oradata/ORCL/shop_idx01.dbf' SIZE 100M;
CREATE USER shop IDENTIFIED BY "Shop#2026" DEFAULT TABLESPACE shop_data QUOTA UNLIMITED ON shop_data QUOTA UNLIMITED ON shop_idx;
GRANT CREATE SESSION, CREATE TABLE, CREATE SEQUENCE, CREATE VIEW TO shop;
CREATE TABLE shop.customers (customer_id NUMBER PRIMARY KEY, email VARCHAR2(80) NOT NULL, full_name VARCHAR2(80) NOT NULL, city VARCHAR2(40), created_at DATE) TABLESPACE shop_data;
CREATE TABLE shop.products (product_id NUMBER PRIMARY KEY, sku VARCHAR2(20) NOT NULL, name VARCHAR2(80) NOT NULL, price NUMBER(10,2) NOT NULL, stock NUMBER NOT NULL) TABLESPACE shop_data;
CREATE TABLE shop.orders (order_id NUMBER PRIMARY KEY, customer_id NUMBER NOT NULL REFERENCES shop.customers (customer_id), order_date DATE, status VARCHAR2(12), total NUMBER(12,2)) TABLESPACE shop_data;
CREATE TABLE shop.order_items (order_id NUMBER NOT NULL REFERENCES shop.orders (order_id), line_no NUMBER NOT NULL, product_id NUMBER NOT NULL REFERENCES shop.products (product_id), quantity NUMBER NOT NULL, unit_price NUMBER(10,2) NOT NULL) TABLESPACE shop_data;
CREATE TABLE shop.payments (payment_id NUMBER PRIMARY KEY, order_id NUMBER NOT NULL REFERENCES shop.orders (order_id), amount NUMBER(12,2) NOT NULL, method VARCHAR2(12), paid_at DATE) TABLESPACE shop_data;
CREATE INDEX shop.orders_customer_ix ON shop.orders (customer_id) TABLESPACE shop_idx;
EXIT

